import argparse, importlib, logging, pkgutil

log = logging.getLogger(__name__)

class Registry:
    def __init__(self):
        self.commands = {}
    def register(self, name, fn, help=""):
        if name in self.commands:
            raise ValueError(f"duplicate command: {name}")
        self.commands[name] = {"fn": fn, "help": help}
    def get(self, name):
        return self.commands[name]
    def names(self):
        return sorted(self.commands)

class API:
    def __init__(self, reg):
        self.reg = reg
        self.log = log
    def register_command(self, name, fn, help=""):
        self.reg.register(name, fn, help)

def load_plugins(package="mycli"):
    reg = Registry()
    api = API(reg)
    pkg = importlib.import_module(package)
    for m in pkgutil.walk_packages(pkg.__path__, prefix=pkg.__name__ + "."):
        name = m.name.rsplit(".", 1)[-1]
        if not name.endswith("_plugin"):
            continue
        try:
            mod = importlib.import_module(m.name)
            if hasattr(mod, "setup"):
                mod.setup(api)
            log.info("loaded plugin: %s", name)
        except Exception:
            log.exception("plugin failed: %s", m.name)
    return reg

def make_parser(reg):
    p = argparse.ArgumentParser(prog="mycli")
    sub = p.add_subparsers(dest="command")
    for name in reg.names():
        c = reg.get(name)
        sub.add_parser(name, help=c["help"])
    return p

def main(argv=None):
    logging.basicConfig(level=logging.INFO)
    reg = load_plugins("mycli")
    args = make_parser(reg).parse_args(argv)
    if not args.command:
        return 0
    try:
        result = reg.get(args.command)["fn"](args)
        return int(result) if result is not None else 0
    except Exception:
        log.exception("command failed: %s", args.command)
        return 1
```

