Design: each shape implements `area` and `perimeter`; a registry maps names to shape objects. The public functions only look up the shape and delegate, preserving the original signatures and unknown-kind behavior. Adding a shape is one registered class, no modified dispatch chains. The brief’s proposed triangle area is not equivalent to the original base/height formula.

```python
import math

_SHAPES = {}

def _shape(name):
    def register(cls):
        _SHAPES[name] = cls()
        return cls
    return register

class _Shape:
    def area(self, a, b=None):
        raise NotImplementedError

    def perimeter(self, a, b=None, c=None):
        raise NotImplementedError

@_shape('circle')
class Circle(_Shape):
    def area(self, a, b=None):
        return math.pi * a * a

    def perimeter(self, a, b=None, c=None):
        return 2 * math.pi * a

@_shape('rect')
class Rectangle(_Shape):
    def area(self, a, b=None):
        return a * b

    def perimeter(self, a, b=None, c=None):
        return 2 * (a + b)

@_shape('tri')
class Triangle(_Shape):
    def area(self, a, b=None):
        return 0.5 * a * b

    def perimeter(self, a, b=None, c=None):
        return a + b + c

def area(kind, a, b=None):
    shape = _SHAPES.get(kind)
    return shape.area(a, b) if shape else None

def perimeter(kind, a, b=None, c=None):
    shape = _SHAPES.get(kind)
    return shape.perimeter(a, b, c) if shape else None
```
